<?php

declare(strict_types=1);

namespace BlueprintAU\Radiant\Database\Schema\Grammars;

use BlueprintAU\Radiant\Database\Schema\Blueprint;
use BlueprintAU\Radiant\Database\Schema\Enums\ColumnType;

/**
 * The Postgres dialect of the schema grammar.
 *
 * Identifiers are quoted with double quotes (embedded quotes doubled).
 * Auto-increment renders as `GENERATED BY DEFAULT AS IDENTITY` (the modern
 * SQL-standard identity column, preferred over `SERIAL`). Postgres supports
 * dropping columns natively.
 */
final class PostgresSchemaGrammar extends SchemaGrammar
{
    /**
     * Wrap an identifier in Postgres double quotes.
     *
     * @param  string  $value
     * @return string
     */
    protected function wrap(string $value): string
    {
        return '"' . str_replace('"', '""', $value) . '"';
    }

    /**
     * Map a logical column type to Postgres' native type.
     *
     * Timestamp types render declared precision (`timestamp(3)`) — a display
     * rounding hint; Postgres always stores microseconds natively.
     *
     * @param  ColumnType  $type
     * @param  int|null  $length
     * @param  int|null  $precision
     * @param  int|null  $scale
     * @return string
     */
    public function type(ColumnType $type, ?int $length = null, ?int $precision = null, ?int $scale = null): string
    {
        return match ($type) {
            ColumnType::String => 'varchar' . $this->suffix($this->requireLength($length)),
            ColumnType::Char => 'char' . $this->suffix($this->requireLength($length)),
            ColumnType::Text => 'text',
            ColumnType::BigInt => 'bigint',
            ColumnType::Int => 'integer',
            ColumnType::Decimal => 'numeric' . $this->suffix($precision, $scale),
            ColumnType::Float => 'double precision',
            ColumnType::Boolean => 'boolean',
            ColumnType::Date => 'date',
            ColumnType::DateTime => 'timestamp' . $this->suffix($precision),
            ColumnType::Timestamp => 'timestamp' . $this->suffix($precision),
            ColumnType::Json => 'jsonb',
            ColumnType::Enum => 'varchar' . $this->suffix($this->requireLength($length)),
            ColumnType::Binary => 'bytea',
            ColumnType::Uuid => 'uuid',
        };
    }

    /**
     * The Postgres auto-increment clause.
     *
     * @return string
     */
    protected function autoIncrement(): string
    {
        return 'GENERATED BY DEFAULT AS IDENTITY';
    }

    /**
     * Postgres 15+ renders the NULLS clause explicitly in both directions.
     *
     * @param  bool  $nullsNotDistinct
     * @return string
     */
    protected function compileNullsNotDistinctClause(bool $nullsNotDistinct): string
    {
        return $nullsNotDistinct ? 'NULLS NOT DISTINCT' : 'NULLS DISTINCT';
    }

    /**
     * Postgres renders partial (filtered) indexes — `CREATE INDEX ... WHERE
     * predicate`.
     *
     * @param  string  $predicate
     * @return string
     */
    protected function compilePartialIndexClause(string $predicate): string
    {
        return 'WHERE ' . $predicate;
    }

    /**
     * Postgres renders `DEFERRABLE [INITIALLY DEFERRED]` on foreign keys.
     *
     * @param  bool  $initiallyDeferred
     * @return string
     */
    protected function compileDeferrableClause(bool $initiallyDeferred): string
    {
        return $initiallyDeferred ? 'DEFERRABLE INITIALLY DEFERRED' : 'DEFERRABLE';
    }

    /**
     * Postgres drops an index by name alone: `DROP INDEX name`.
     *
     * @param  string  $name
     * @param  string  $table
     * @return string
     */
    public function compileDropIndex(string $name, string $table): string
    {
        unset($table);
        $this->assertValidIdentifier($name);

        return 'DROP INDEX ' . $this->wrap($name);
    }

    /**
     * Compile an `ALTER TABLE ... DROP COLUMN` statement.
     *
     * @param  Blueprint  $blueprint
     * @return string
     */
    protected function compileDropColumn(Blueprint $blueprint): string
    {
        $table = $blueprint->getTable();
        $columns = $blueprint->getDropColumns();
        if ($columns === []) {
            throw new \InvalidArgumentException('Cannot drop columns with no columns defined.');
        }

        return 'ALTER TABLE ' . $this->wrap($table) . ' DROP COLUMN ' . implode(', DROP COLUMN ', array_map(
            fn (string $column) => $this->wrap($column),
            $columns,
        ));
    }

    /**
     * Compile the `ALTER TABLE ... ALTER COLUMN` statements — Postgres'
     * in-place content-drift form.
     *
     * @param  Blueprint  $blueprint
     * @return list<string>
     */
    public function compileModifyColumn(Blueprint $blueprint): array
    {
        $table = $blueprint->getTable();
        $columns = $blueprint->getColumns();
        if ($columns === []) {
            throw new \InvalidArgumentException('Cannot modify columns with no columns defined.');
        }

        $statements = [];

        foreach ($columns as $column) {
            $name = $this->wrap($column['name']);
            $base = 'ALTER TABLE ' . $this->wrap($table) . ' ALTER COLUMN ' . $name;

            // TYPE first: the type text is the identity of the change, and
            // a type change must land before constraints that depend on it.
            $statements[] = $base . ' TYPE ' . $this->type($column['type'], $column['length']);

            // Nullability second: SET NOT NULL validates existing rows, so
            // it must come after the type conversion.
            $statements[] = $column['nullable'] ? $base . ' DROP NOT NULL' : $base . ' SET NOT NULL';

            // Default last: a null desired default means DROP DEFAULT (the
            // column carries no default); anything else renders the literal.
            $statements[] = $column['default'] === null
                ? $base . ' DROP DEFAULT'
                : $base . ' SET DEFAULT ' . $this->compileDefault($column['default']);
        }

        return $statements;
    }

    /**
     * Compile an `ALTER TABLE ... ADD CONSTRAINT ... FOREIGN KEY`
     * statement — Postgres' in-place FK-add form.
     *
     * @param  string  $table
     * @param  array{columns: list<string>, references: list<string>, onDelete: \BlueprintAU\Radiant\Database\Schema\Enums\ForeignKeyAction|null, onUpdate: \BlueprintAU\Radiant\Database\Schema\Enums\ForeignKeyAction|null, deferrable: bool, initiallyDeferred: bool}  $foreignKey
     * @param  string  $name
     * @return string
     */
    public function compileAddForeignKey(string $table, array $foreignKey, string $name): string
    {
        $this->assertValidIdentifier($name);

        return 'ALTER TABLE ' . $this->wrap($table) . ' ADD CONSTRAINT ' . $this->wrap($name) . ' '
            . $this->compileForeignKeyConstraint($foreignKey);
    }

    /**
     * Compile an `ALTER TABLE ... DROP CONSTRAINT` statement — Postgres'
     * in-place constraint-drop form (covers FKs and CHECKs).
     *
     * @param  string  $table
     * @param  string  $name
     * @return string
     */
    public function compileDropForeignKey(string $table, string $name): string
    {
        $this->assertValidIdentifier($name);

        return 'ALTER TABLE ' . $this->wrap($table) . ' DROP CONSTRAINT ' . $this->wrap($name);
    }

    /**
     * Compile an `ALTER TABLE ... ADD CONSTRAINT ... CHECK` statement —
     * Postgres' in-place CHECK-add form.
     *
     * @param  string  $table
     * @param  string  $name
     * @param  string  $expression
     * @return string
     */
    public function compileAddCheck(string $table, string $name, string $expression): string
    {
        $this->assertValidIdentifier($name);

        return 'ALTER TABLE ' . $this->wrap($table) . ' ADD CONSTRAINT ' . $this->wrap($name)
            . ' CHECK (' . $expression . ')';
    }

    /**
     * Compile an `ALTER TABLE ... DROP CONSTRAINT` statement for a CHECK.
     *
     * @param  string  $table
     * @param  string  $name
     * @return string
     */
    public function compileDropCheck(string $table, string $name): string
    {
        $this->assertValidIdentifier($name);

        return 'ALTER TABLE ' . $this->wrap($table) . ' DROP CONSTRAINT ' . $this->wrap($name);
    }

    /**
     * Postgres caps identifiers at 63 bytes — fail fast at compile time,
     * never silently truncate.
     *
     * @param  string  $name
     * @return void
     * @throws \InvalidArgumentException
     */
    public function assertValidIdentifier(string $name): void
    {
        if (strlen($name) > 63) {
            throw new \InvalidArgumentException(sprintf(
                'Identifier [%s] exceeds Postgres\'s 63-byte limit (%d bytes); '
                . 'declare a shorter #[Unique(name: ...)] / #[Index(name: ...)].',
                $name,
                strlen($name),
            ));
        }
    }
}